const baseState={version:4,view:'quiz',q:0,answers:Array(9).fill(null),birth:{date:'',time:'12:00',unknown:false},pureConfig:{wrist:16,size:8},chart:null,recommended:[],selectionDetails:[],pureRecipes:[],mixedRecipe:[],carouselIndex:0,result:false,libraryFilter:'全部',search:'',libraryReturn:'quiz',custom:null};
const state=JSON.parse(JSON.stringify(baseState));try{const saved=JSON.parse(sessionStorage.getItem('jingyu-result-v4'));if(saved?.version===4&&saved.result)Object.assign(state,saved)}catch{}if(!state.pureConfig)state.pureConfig={wrist:+state.birth.wrist||16,size:+state.birth.size||8};
const sprite=new Image();sprite.src='assets/beads.png';
function beadStyle(id){const c=crystals[id];return `background-position:${c.visual%4*100/3}% ${Math.floor(c.visual/4)*100/3}%;filter:${c.filter}`}
function bead(id){return `<span class="bead" style="${beadStyle(id)}"></span>`}
function legend(recipe){return recipe.map(r=>`<span><i style="background:${crystals[r.id].hex}"></i>${crystals[r.id].name} ${r.n} 颗</span>`).join('')}
function renderQuiz(){const q=questions[state.q],total=questions.length;$('#panel').innerHTML=`<div class="panel-head"><span>性格与愿望探索</span><span>${String(state.q+1).padStart(2,'0')} / ${String(total).padStart(2,'0')} · 约 3 分钟</span></div><div class="progress"><div style="width:${(state.q+1)/total*100}%"></div></div><p class="question-kicker">${questionTopics[state.q]}</p><h2>${q[0]}</h2><p class="muted">${state.q===8?'请选择此刻最重要的一个方向。':'没有标准答案，选择更接近此刻的自己。'}</p><div class="answers ${state.q===8?'goal-answers':''}">${q[1].map((a,i)=>`<button class="answer ${state.answers[state.q]===i?'selected':''}" data-answer="${i}" aria-pressed="${state.answers[state.q]===i}"><i>${String.fromCharCode(65+i)}</i><span>${a}</span></button>`).join('')}</div><div class="actions"><button class="secondary" id="prev" ${state.q===0?'disabled':''}>上一题</button><button class="primary" id="next" ${state.answers[state.q]===null?'disabled':''}>${state.q===total-1?'继续填写出生信息':'下一题'}</button></div><p class="fine">你的选择与出生信息仅在当前页面和本次会话中计算，不上传服务器。</p>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{state.answers[state.q]=+b.dataset.answer;state.result=false;renderQuiz()});$('#prev').onclick=()=>{state.q--;renderQuiz()};$('#next').onclick=()=>state.q<total-1?(state.q++,renderQuiz()):show('birth')}
function show(view,push=true){if(view==='result'&&!state.result){if(state.answers.includes(null)){state.q=state.answers.indexOf(null);view='quiz'}else view='birth'}state.view=view;const isResult=view==='result',isLibrary=view==='library';$('#appShell').hidden=isResult||isLibrary;$('#resultPage').hidden=!isResult;$('#libraryPage').hidden=!isLibrary;document.body.classList.toggle('result-mode',isResult||isLibrary);if(view==='quiz')renderQuiz();else if(view==='birth')renderBirth();else if(view==='library')library();else renderResult();if(push)history.pushState({view},'',`#${view}`);window.scrollTo({top:0,behavior:'instant'})}
function renderBirth(){$('#panel').innerHTML=`<p class="question-kicker">02 / 东方命盘</p><h2>记录你与世界相遇的时刻。</h2><p class="muted">以公历、北京时间（UTC+8）排盘。暂不校正真太阳时；海外出生请先换算北京时间。</p><form id="birthForm"><label for="date">出生日期 · 公历</label><input required id="date" type="date" min="1901-01-01" max="${new Date().toISOString().slice(0,10)}" value="${state.birth.date}"><label for="time">出生时间 · 北京时间</label><input id="time" type="time" value="${state.birth.time}" ${state.birth.unknown?'disabled':''}><label class="check"><input id="unknown" type="checkbox" ${state.birth.unknown?'checked':''}> 不确定时辰（仅分析前三柱）</label><p id="formError" class="error" role="alert"></p><div class="actions"><button type="button" class="secondary" id="backQuiz">返回问卷</button><button class="primary" type="submit">生成分析与手串</button></div></form>`;$('#unknown').onchange=e=>$('#time').disabled=e.target.checked;$('#backQuiz').onclick=()=>{saveBirth();show('quiz')};$('#birthForm').onsubmit=e=>{e.preventDefault();saveBirth();if(state.answers.includes(null)){$('#formError').textContent='请先完成全部 9 道问题。';return}try{generate();show('result')}catch(err){$('#formError').textContent='排盘暂未完成，请检查出生日期和时间后重试。'}}}
