function addFreeBead(id,source){const capacity=getFreeCapacity();if(state.custom.sequence.length>=capacity)return;state.custom.sequence.push(id);animateBeadToBracelet(source,id,state.custom.sequence.length-1,capacity);updateCustomPreview();renderFreeButtons()}
