function drawFreeBracelet(canvas,sequence,capacity){if(!canvas)return;const ctx=canvas.getContext('2d'),radius=295,selected=state.custom.selected,average=selected.reduce((sum,id)=>sum+state.custom.sizes[id],0)/selected.length,scale=Math.min(13,2*Math.PI*radius/(capacity*average)*.98);ctx.clearRect(0,0,900,900);for(let i=0;i<capacity;i++){const a=-Math.PI/2+i/capacity*Math.PI*2,x=450+Math.cos(a)*radius,y=450+Math.sin(a)*radius,id=sequence[i];if(id!==undefined&&sprite.complete&&sprite.naturalWidth)drawBead(ctx,id,x,y,state.custom.sizes[id]*scale);else{ctx.save();ctx.beginPath();ctx.arc(x,y,Math.max(25,average*scale*.42),0,Math.PI*2);ctx.setLineDash([8,9]);ctx.lineWidth=3;ctx.strokeStyle='#71807888';ctx.stroke();ctx.restore()}}}
